src/runtime/blackboard.ts.source:
/**
 * 黑板：rooms/<room>/state/<role>.json per-role 分片读写。
 * 保留态三元组（running/blocked/done）强制为 shard.status；业务子状态放
 * ext 字段仅展示。同 role 并发写属协议违规（单写者约定，与事件流一致）；
 * 跨 role 分片天然路径隔离。
 */
import { existsSync } from "node:fs";
import { readdir } from "node:fs/promises";
import { join } from "node:path";
import { roomLayout } from "./paths.js";
import { isReservedStage } from "./types.js";
import { readJson, writeJsonAtomic } from "./fs-utils.js";
import { RuntimeError } from "./errors.js";

/** 黑板分片：保留态 + 自由业务负载（ext 仅展示，不参与归约）。 */
export interface Shard {
  role: string;
  status: string;
  /** 业务子状态/任意展示性负载。 */
  ext?: unknown;
  updatedAt: number;
}

/**
 * 写入角色分片。status 必须是保留态三元组之一——黑板是巡场归约的数据源，
 * 非法值会让「阻塞高亮/闭环判定」失去意义，直接拒绝。
 */
export async function setShard(
  teamHome: string,
  room: string,
  role: string,
  shard: Omit<Shard, "role" | "updatedAt"> & { ext?: unknown },
): Promise<Shard> {
  if (!isReservedStage(shard.status)) {
    throw new RuntimeError(
      "invalid-stage",
      `blackboard status must be one of running|blocked|done, got: ${shard.status}`,
    );
  }
  const full: Shard = { ...shard, role, status: shard.status, updatedAt: Date.now() };
  await writeJsonAtomic(join(roomLayout(teamHome, room).stateDir, `${role}.json`), full);
  return full;
}

/** 读角色分片；不存在返回 undefined。 */
export async function getShard(
  teamHome: string,
  room: string,
  role: string,
): Promise<Shard | undefined> {
  return readJson<Shard>(join(roomLayout(teamHome, room).stateDir, `${role}.json`));
}

/** 列出房间全部分片。 */
export async function listShards(teamHome: string, room: string): Promise<Shard[]> {
  const stateDir = roomLayout(teamHome, room).stateDir;
  if (!existsSync(stateDir)) return [];
  const shards: Shard[] = [];
  for (const entry of await readdir(stateDir)) {
    if (!entry.endsWith(".json")) continue;
    const shard = await readJson<Shard>(join(stateDir, entry));
    if (shard) shards.push(shard);
  }
  return shards.sort((a, b) => a.role.localeCompare(b.role));
}

src/runtime/cas-lock.ts.source:
/**
 * CAS 锁（room.lock + instance-id 幂等键，v2.2 定稿 §5）。
 *
 * 语义：
 * - acquire：`open(path, 'wx')` 原子创建；已存在时读 holder——
 *   同 instanceId → 幂等重入成功；异 holder → Conflict；
 *   空/坏内容 → 孤儿锁（acquire 到写 holder 之间崩溃的产物），默认拒绝，
 *   仅当显式 `takeoverOrphan` 时接管（接管是显式决策，不做自动过期）。
 * - release：re-read 校验 holder 后 unlink；非持有者拒绝。
 * - 死锁恢复归巡场对账职责（人工/规程删残留锁或显式 takeover），本层无 TTL。
 */
import { open, readFile, unlink, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { LockError } from "./errors.js";
import type { LockInfo } from "./types.js";

async function readLock(lockPath: string): Promise<LockInfo | undefined> {
  if (!existsSync(lockPath)) return undefined;
  const raw = await readFile(lockPath, "utf8");
  if (raw.trim() === "") return undefined;
  try {
    const parsed = JSON.parse(raw) as Partial<LockInfo>;
    if (typeof parsed.holder !== "string") return undefined;
    return { holder: parsed.holder, acquiredAt: parsed.acquiredAt ?? 0 };
  } catch {
    return undefined;
  }
}

export type AcquireResult = "acquired" | "reentered";

/**
 * 原子获取 CAS 锁。
 * @param lockPath 锁文件路径（如 room.lock）。
 * @param instanceId 持有者幂等键（约定为主会话 id，跨重启稳定）。
 * @param opts.takeoverOrphan 锁文件存在但为空/坏内容（孤儿锁）时强制接管。
 * @throws LockConflictError 已被其他实例持有；LockError 其他失败。
 */
export async function acquireCas(
  lockPath: string,
  instanceId: string,
  opts: { takeoverOrphan?: boolean } = {},
): Promise<AcquireResult> {
  // 快路径：幂等重入与孤儿判定都先读一次，避免无谓的创建冲突。
  if (existsSync(lockPath)) {
    const existing = await readLock(lockPath);
    if (existing === undefined) {
      if (!opts.takeoverOrphan) {
        throw new LockError(
          "orphan-lock",
          `orphan lock at ${lockPath} (empty or corrupt); retry with takeoverOrphan to take over`,
        );
      }
      return writeHolder(lockPath, instanceId, "acquired");
    }
    if (existing.holder === instanceId) return "reentered";
    throw new LockConflictError(lockPath, existing.holder);
  }

  let handle;
  try {
    handle = await open(lockPath, "wx");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "EEXIST") {
      // 竞态窗口内被他人抢先：走慢路径复判。
      return acquireCas(lockPath, instanceId, opts);
    }
    throw error;
  }
  try {
    await handle.writeFile(JSON.stringify({ holder: instanceId, acquiredAt: Date.now() }), "utf8");
  } finally {
    await handle.close();
  }
  return "acquired";
}

async function writeHolder(lockPath: string, instanceId: string, result: AcquireResult): Promise<AcquireResult> {
  // 接管孤儿：unlink + wx 重建，保证内容完整原子落位（中间空窗极短且
  // 孤儿本身即无主状态，无并发保护对象）。
  await unlink(lockPath);
  const handle = await open(lockPath, "wx");
  try {
    await handle.writeFile(JSON.stringify({ holder: instanceId, acquiredAt: Date.now() }), "utf8");
  } finally {
    await handle.close();
  }
  void result;
  return "acquired";
}

/**
 * 释放锁：re-read 校验 holder 后删除。
 * @throws LockError 非持有者；锁不存在时静默成功（幂等清理）。
 */
export async function releaseCas(lockPath: string, instanceId: string): Promise<void> {
  const existing = await readLock(lockPath);
  if (existing === undefined) {
    // 不存在（含孤儿空文件）：视为已释放。
    if (existsSync(lockPath)) await unlink(lockPath);
    return;
  }
  if (existing.holder !== instanceId) {
    throw new LockConflictError(lockPath, existing.holder);
  }
  await unlink(lockPath);
}

/** 持锁执行 fn，结束（含异常）后释放。 */
export async function withCasLock<T>(
  lockPath: string,
  instanceId: string,
  fn: () => Promise<T>,
): Promise<T> {
  await acquireCas(lockPath, instanceId);
  try {
    return await fn();
  } finally {
    await releaseCas(lockPath, instanceId);
  }
}

/** 读当前锁信息（诊断用）。 */
export async function peekLock(lockPath: string): Promise<LockInfo | undefined> {
  return readLock(lockPath);
}

export class LockConflictError extends LockError {
  constructor(lockPath: string, holder: string) {
    super("lock-conflict", `lock ${lockPath} is held by another instance: ${holder}`);
  }
}

src/runtime/errors.ts.source:
/** runtime 统一错误类型：工具层（P3）按 code 装配模型可读的拒绝理由。 */

export class RuntimeError extends Error {
  /** 稳定小写 kebab 错误码，供上游路由与断言。 */
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = "RuntimeError";
    this.code = code;
  }
}

export class LedgerError extends RuntimeError {
  constructor(code: string, message: string) {
    super(code, message);
    this.name = "LedgerError";
  }
}

export class LockError extends RuntimeError {
  constructor(code: string, message: string) {
    super(code, message);
    this.name = "LockError";
  }
}

export class GateError extends RuntimeError {
  constructor(code: string, message: string) {
    super(code, message);
    this.name = "GateError";
  }
}

src/runtime/event-log.ts.source:
/**
 * append-only 事件流（rooms/<room>/events.jsonl，仅运行时单写者）。
 *
 * 单写者约定：同一房间同时只允许一个运行时实例写入（多 room 并行写各自
 * events.jsonl 允许）；双实例并发写同 room 属协议违规，本层不做跨进程仲裁。
 *
 * 崩溃容错：append 半途 kill 会留下截断尾行——初始化扫描与回放读取均跳过
 * 末尾坏行并如实报告（tornTail），不因坏行抛错。
 */
import { existsSync } from "node:fs";
import { readFile, stat, writeFile } from "node:fs/promises";
import type { EventRecord } from "./types.js";

export interface AppendInput {
  session_id: string;
  actor: string;
  type: string;
  payload?: unknown;
}

export interface ReadResult {
  events: EventRecord[];
  /** 解析失败的行号列表（1-based 数据行）。 */
  corruptLines: number[];
}

/** 单写者互斥文件：同 room 的 writer 锁名。 */
export const WRITER_LOCK_SUFFIX = ".writer";

export class EventLog {
  private readonly file: string;
  private nextSeq = 1;
  private tornTail = false;

  constructor(file: string) {
    this.file = file;
  }

  /**
   * 扫描现有事件恢复 seq 游标；末尾截断坏行不抛错，标记 tornTail。
   * 必须在首次 append 前调用。
   */
  async init(): Promise<void> {
    if (!existsSync(this.file)) {
      this.nextSeq = 1;
      this.tornTail = false;
      return;
    }
    const raw = await readFile(this.file, "utf8");
    let max = 0;
    let torn = false;
    const lines = raw.split("\n").filter((l) => l !== "");
    for (let i = 0; i < lines.length; i++) {
      try {
        const rec = JSON.parse(lines[i]!) as EventRecord;
        if (typeof rec.seq === "number" && rec.seq > max) max = rec.seq;
      } catch {
        // 仅末尾坏行视为 torn tail；中间坏行同样跳过但一并标记。
        torn = true;
        void i;
      }
    }
    this.nextSeq = max + 1;
    this.tornTail = torn;
  }

  /** 初始化时是否发现解析失败行。 */
  hasTornTail(): boolean {
    return this.tornTail;
  }

  /** 追加一条事件（副作用记账唯一入口）；返回带 seq 的完整记录。 */
  async append(input: AppendInput): Promise<EventRecord> {
    const record: EventRecord = {
      seq: this.nextSeq++,
      ts: Date.now(),
      session_id: input.session_id,
      actor: input.actor,
      type: input.type,
      payload: input.payload ?? null,
    };
    await writeFile(this.file, JSON.stringify(record) + "\n", { flag: "a", encoding: "utf8" });
    return record;
  }

  /**
   * 回放读取（fromSeq 起全量）。坏行跳过并计入 corruptLines；
   * 空文件返回空数组。
   */
  async read(fromSeq = 1): Promise<ReadResult> {
    if (!existsSync(this.file)) return { events: [], corruptLines: [] };
    const raw = await readFile(this.file, "utf8");
    const events: EventRecord[] = [];
    const corruptLines: number[] = [];
    const lines = raw.split("\n");
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!;
      if (line === "") continue;
      try {
        const rec = JSON.parse(line) as EventRecord;
        if (rec.seq >= fromSeq) events.push(rec);
      } catch {
        corruptLines.push(i + 1);
      }
    }
    return { events, corruptLines };
  }

  /** 当前已用事件数（诊断/对账用）。 */
  async count(): Promise<number> {
    if (!existsSync(this.file)) return 0;
    const { size } = await stat(this.file);
    return size === 0 ? 0 : this.read().then((r) => r.events.length);
  }
}

src/runtime/fs-utils.ts.source:
/**
 * 原子文件原语：同目录唯一临时文件 + rename（POSIX 同目录 rename 原子）。
 * 故障模型为进程崩溃（page cache 不丢）；掉电级持久性（父目录 fsync）属
 * 过度设计，不在此实现。
 */
import { link, mkdir, readdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { basename, dirname, join } from "node:path";

/** 临时文件前缀；目录枚举时须过滤，recovery 负责清扫。 */
export const TMP_PREFIX = ".tmp-";

/** 确保目录存在（递归）。 */
export async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

/**
 * 原子写 JSON：先写同目录临时文件再 rename 到位。
 * 崩溃只可能残留临时文件（不影响读者），由 {@link sweepTmp} 清扫。
 */
export async function writeJsonAtomic(file: string, value: unknown): Promise<void> {
  const dir = dirname(file);
  await ensureDir(dir);
  const tmp = join(dir, `${TMP_PREFIX}${basename(file)}-${process.pid}-${Math.random().toString(36).slice(2)}`);
  await writeFile(tmp, JSON.stringify(value, null, 2), "utf8");
  await rename(tmp, file);
}

/** 读 JSON 文件；不存在时返回 undefined。 */
export async function readJson<T>(file: string): Promise<T | undefined> {
  if (!existsSync(file)) return undefined;
  return JSON.parse(await readFile(file, "utf8")) as T;
}

/**
 * 清扫目录内的原子写临时残片（一级）。
 * @returns 清除的文件数。
 */
export async function sweepTmp(dir: string): Promise<number> {
  if (!existsSync(dir)) return 0;
  let swept = 0;
  for (const entry of await readdir(dir)) {
    if (!entry.startsWith(TMP_PREFIX)) continue;
    const full = join(dir, entry);
    const s = await stat(full);
    if (s.isFile()) {
      await rm(full);
      swept += 1;
    }
  }
  return swept;
}

/**
 * 归档落点限位判定：target 必须落在 root 内（防越界写入）。
 * @returns 解析后的绝对目标路径。
 */
export function confineToRoot(root: string, target: string): string {
  const resolvedRoot = root.startsWith("/") ? root : join(process.cwd(), root);
  const resolvedTarget = target.startsWith("/") ? target : join(resolvedRoot, target);
  if (!resolvedTarget.startsWith(resolvedRoot.endsWith("/") ? resolvedRoot : resolvedRoot + "/")) {
    throw new Error(`archive target escapes TEAM_HOME: ${target}`);
  }
  return resolvedTarget;
}

/**
 * 原子 create-if-not-exists 复制引用：target 已存在时抛 EEXIST（不覆盖）。
 * Node 无 RENAME_NOREPLACE；防覆盖发布只能用 link。
 * @returns true = 本次创建；false = target 已存在（调用方决定残片处理）。
 */
export async function linkNoReplace(src: string, target: string): Promise<boolean> {
  try {
    await link(src, target);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "EEXIST") return false;
    throw error;
  }
}

src/runtime/gates.ts.source:
/**
 * gates/<id>.json 读写：pending → approved/denied 单向（Console 唯一写点的
 * 协议面；本层只提供原语，HTTP 路由属 P5 宿主层）。
 */
import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { GateRecord, GateStatus } from "./types.js";
import { GateError } from "./errors.js";
import { readJson, writeJsonAtomic } from "./fs-utils.js";

export interface NewGate {
  id: string;
  reason: string;
  requestedBy: string;
}

/** 打开闸口（status=pending）；同 id 已存在即拒（幂等键 = gate id）。 */
export async function openGate(gatesDir: string, input: NewGate): Promise<GateRecord> {
  const file = join(gatesDir, `${input.id}.json`);
  const existing = await readJson<GateRecord>(file);
  if (existing !== undefined) {
    throw new GateError("gate-exists", `gate ${input.id} already exists (${existing.status})`);
  }
  const record: GateRecord = {
    id: input.id,
    status: "pending",
    reason: input.reason,
    requestedBy: input.requestedBy,
    requestedAt: Date.now(),
  };
  await writeJsonAtomic(file, record);
  return record;
}

/** 读单个 gate；不存在返回 undefined。 */
export async function readGate(gatesDir: string, id: string): Promise<GateRecord | undefined> {
  return readJson<GateRecord>(join(gatesDir, `${id}.json`));
}

/**
 * 裁决：pending → approved/denied 单向；非 pending 即拒（不可逆，无重开）。
 * @param by 裁决主体（Console 审计字段）。
 */
export async function resolveGate(
  gatesDir: string,
  id: string,
  decision: Exclude<GateStatus, "pending">,
  by: string,
): Promise<GateRecord> {
  const file = join(gatesDir, `${id}.json`);
  const current = await readJson<GateRecord>(file);
  if (current === undefined) {
    throw new GateError("gate-not-found", `gate ${id} does not exist`);
  }
  if (current.status !== "pending") {
    throw new GateError("gate-resolved", `gate ${id} already resolved to ${current.status}`);
  }
  const next: GateRecord = {
    ...current,
    status: decision,
    ...(decision === "approved" || decision === "denied"
      ? { resolvedBy: by, resolvedAt: Date.now() }
      : {}),
  };
  await writeJsonAtomic(file, next);
  return next;
}

/** 枚举全部 gate（跳过损坏文件并如实报告）。 */
export async function listGates(
  gatesDir: string,
): Promise<{ gates: GateRecord[]; corrupt: string[] }> {
  let entries: string[];
  try {
    entries = await readdir(gatesDir);
  } catch {
    return { gates: [], corrupt: [] };
  }
  const gates: GateRecord[] = [];
  const corrupt: string[] = [];
  for (const entry of entries) {
    if (!entry.endsWith(".json")) continue;
    try {
      const rec = JSON.parse(await readFile(join(gatesDir, entry), "utf8")) as unknown;
      if (isGateRecord(rec)) gates.push(rec);
      else corrupt.push(entry);
    } catch {
      corrupt.push(entry);
    }
  }
  return { gates, corrupt };
}

function isGateRecord(value: unknown): value is GateRecord {
  const v = value as GateRecord;
  return (
    typeof v === "object" &&
    v !== null &&
    typeof v.id === "string" &&
    (["pending", "approved", "denied"] as const).includes(v.status)
  );
}

src/runtime/ledger.ts.source:
/**
 * 共享任务账本：每任务单文件原子写 + 状态机合法迁移强制（v2.2 定稿 §5）。
 * touched paths / mutexGroups 的分组互斥判定原语供工具层（P3）装配。
 */
import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import { mkdir, readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { canTransition, type TaskRecord, type TaskStatus } from "./types.js";
import { LedgerError } from "./errors.js";
import { readJson, sweepTmp, writeJsonAtomic } from "./fs-utils.js";

/** 创建任务时的输入（id/rev/时间戳由账本生成）。 */
export interface NewTask {
  title: string;
  room: string;
  assignee?: string;
  touched?: string[];
  mutexGroups?: string[];
  maxRounds?: number;
  dod?: string[];
  baseline?: string;
}

/** 更新任务时的补丁：status 走状态机校验；其余字段浅覆盖。 */
export interface TaskPatch {
  title?: string;
  status?: TaskStatus;
  assignee?: string;
  touched?: string[];
  mutexGroups?: string[];
  rounds?: number;
  maxRounds?: number;
  dod?: string[];
  baseline?: string;
  artifact?: string;
}

export interface UpdateOptions {
  /** 乐观并发：期望的当前 rev，不匹配即拒绝（P3「读-判-写」原子性钩子）。 */
  expectRev?: number;
}

export class Ledger {
  private readonly tasksDir: string;

  constructor(teamHome: string, tasksDir: string) {
    this.tasksDir = tasksDir ?? join(teamHome, "ledger", "tasks");
  }

  /** 创建任务，返回初始记录（status=queued, rev=1）。 */
  async create(input: NewTask): Promise<TaskRecord> {
    const now = Date.now();
    const record: TaskRecord = {
      id: `task-${randomUUID()}`,
      title: input.title,
      status: "queued",
      room: input.room,
      ...(input.assignee !== undefined ? { assignee: input.assignee } : {}),
      touched: input.touched ?? [],
      mutexGroups: input.mutexGroups ?? [],
      rounds: 0,
      maxRounds: input.maxRounds ?? 0,
      dod: input.dod ?? [],
      ...(input.baseline !== undefined ? { baseline: input.baseline } : {}),
      rev: 1,
      createdAt: now,
      updatedAt: now,
    };
    await writeJsonAtomic(this.taskFile(record.id), record);
    return record;
  }

  /** 读单个任务；不存在返回 undefined。 */
  async get(id: string): Promise<TaskRecord | undefined> {
    return readJson<TaskRecord>(this.taskFile(id));
  }

  /**
   * 状态机受控更新。status 迁移非法即拒；expectRev 不匹配即拒；
   * rounds 只能单调递增。成功后 rev+1 并原子落盘。
   */
  async update(id: string, patch: TaskPatch, opts: UpdateOptions = {}): Promise<TaskRecord> {
    const current = await this.get(id);
    if (current === undefined) {
      throw new LedgerError("task-not-found", `task ${id} does not exist`);
    }
    if (opts.expectRev !== undefined && opts.expectRev !== current.rev) {
      throw new LedgerError(
        "rev-conflict",
        `task ${id} rev mismatch: expected ${opts.expectRev}, current ${current.rev}`,
      );
    }
    if (patch.status !== undefined && !canTransition(current.status, patch.status)) {
      throw new LedgerError(
        "illegal-transition",
        `task ${id}: illegal transition ${current.status} -> ${patch.status}`,
      );
    }
    if (patch.rounds !== undefined && patch.rounds < current.rounds) {
      throw new LedgerError("rounds-regress", `task ${id}: rounds cannot decrease`);
    }
    const next: TaskRecord = {
      ...current,
      ...patch,
      rev: current.rev + 1,
      updatedAt: Date.now(),
    };
    if (patch.rounds !== undefined && next.maxRounds > 0 && next.rounds > next.maxRounds) {
      throw new LedgerError(
        "rounds-exceeded",
        `task ${id}: rounds ${next.rounds} exceeds max ${next.maxRounds}`,
      );
    }
    await writeJsonAtomic(this.taskFile(id), next);
    return next;
  }

  /** 列出全部任务（跳过临时残片与损坏文件——损坏文件名会出现在结果 warnings）。 */
  async list(): Promise<{ tasks: TaskRecord[]; corrupt: string[] }> {
    if (!existsSync(this.tasksDir)) {
      await mkdir(this.tasksDir, { recursive: true });
    }
    const entries = await readdir(this.tasksDir);
    const tasks: TaskRecord[] = [];
    const corrupt: string[] = [];
    for (const entry of entries) {
      if (!entry.endsWith(".json")) continue;
      try {
        const raw = JSON.parse(await readFile(join(this.tasksDir, entry), "utf8")) as unknown;
        if (raw === undefined || typeof raw !== "object" || typeof (raw as TaskRecord).id !== "string") {
          corrupt.push(entry);
          continue;
        }
        tasks.push(raw as TaskRecord);
      } catch {
        corrupt.push(entry);
      }
    }
    return { tasks, corrupt };
  }

  private taskFile(id: string): string {
    return join(this.tasksDir, `${id}.json`);
  }

  /** 清扫本目录内的临时残片，返回清除数。 */
  async sweepTmpFiles(): Promise<number> {
    return sweepTmp(this.tasksDir);
  }
}


/**
 * 分组互斥断言原语：同房间 running 任务间，共享任一 mutexGroup 或
 * touched 字面交集非空即冲突（定稿 §6.1「同组互斥才允许 active」）。
 * @returns 冲突对清单；空数组 = 无冲突。
 */
export function findConflicts(
  tasks: TaskRecord[],
): Array<{ a: string; b: string; reason: string }> {
  const active = tasks.filter((t) => t.status === "running");
  const conflicts: Array<{ a: string; b: string; reason: string }> = [];
  for (let i = 0; i < active.length; i++) {
    for (let j = i + 1; j < active.length; j++) {
      const a = active[i]!;
      const b = active[j]!;
      if (a.room !== b.room) continue;
      const sharedGroup = a.mutexGroups.find((g) => b.mutexGroups.includes(g));
      if (sharedGroup !== undefined) {
        conflicts.push({ a: a.id, b: b.id, reason: `shared mutex group: ${sharedGroup}` });
        continue;
      }
      const overlap = a.touched.find((p) => b.touched.includes(p));
      if (overlap !== undefined) {
        conflicts.push({ a: a.id, b: b.id, reason: `touched path overlap: ${overlap}` });
      }
    }
  }
  return conflicts;
}

src/runtime/mailbox.ts.source:
/**
 * 信箱三段式投递协议（v2.2 定稿 §3 mailbox，omo 模式）。
 *
 * 三段：<member>/<uuid>.json（待读）→ .delivering-<uuid>.json（消费者 claim 态）
 * → processed/<uuid>.json（已确认）。
 *
 * 语义钉死（对抗评审 M1/M2）：
 * - `.delivering-` 前缀单义化为「消费者 claim 态」；发送方暂存走原子写临时
 *   文件生态（.tmp-），不占用 delivering 位。
 * - 发布/claim 均用 linkNoReplace（create-if-not-exists）：待读位已存在 =
 *   double-inject；delivering 已存在 = 已被认领或残片冲突——绝不用裸 rename
 *   （静默覆盖）。
 * - at-least-once：claim 态超 TTL 会被收割重投，消费者必须按信封 id 幂等处理。
 */
import { readdir, rm } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { linkNoReplace, readJson, TMP_PREFIX, writeJsonAtomic } from "./fs-utils.js";
import { memberMailboxDir } from "./paths.js";
import { recoverDeliveries } from "./recovery.js";

export const DELIVERING_PREFIX = ".delivering-";
export const PROCESSED_DIR = "processed";

/** 信封：信箱文件的协议内容。 */
export interface Envelope {
  id: string;
  from: string;
  to: string;
  type: string;
  body: unknown;
  createdAt: number;
}

function unreadFile(memberDir: string, uuid: string): string {
  return join(memberDir, `${uuid}.json`);
}

function deliveringFile(memberDir: string, uuid: string): string {
  return join(memberDir, `${DELIVERING_PREFIX}${uuid}.json`);
}

function processedFile(memberDir: string, uuid: string): string {
  return join(memberDir, PROCESSED_DIR, `${uuid}.json`);
}

/**
 * 投递一条消息到成员待读位。
 * @returns 信封 id（= uuid）。
 * @throws Error 目标已存在（double-inject）。
 */
export async function deliver(
  teamHome: string,
  to: string,
  message: { from: string; type: string; body: unknown },
  opts: { id?: string } = {},
): Promise<string> {
  const memberDir = memberMailboxDir(teamHome, to);
  const id = opts.id ?? crypto.randomUUID();
  const envelope: Envelope = {
    id,
    from: message.from,
    to,
    type: message.type,
    body: message.body,
    createdAt: Date.now(),
  };
  // 发送方暂存（.tmp- 生态、隐藏名不进待读枚举）→ link 原子发布 → 清暂存。
  const staged = join(memberDir, `${TMP_PREFIX}outgoing-${id}.json`);
  await writeJsonAtomic(staged, envelope);
  const published = await linkNoReplace(staged, unreadFile(memberDir, id));
  if (!published) {
    await rm(staged);
    throw new Error(`double-inject: envelope ${id} already in ${to}'s mailbox`);
  }
  await rm(staged);
  return id;
}

/** 列出成员待读信封。 */
export async function readUnread(teamHome: string, member: string): Promise<Envelope[]> {
  const memberDir = memberMailboxDir(teamHome, member);
  if (!existsSync(memberDir)) return [];
  const out: Envelope[] = [];
  for (const entry of await readdir(memberDir)) {
    if (!entry.endsWith(".json") || entry.startsWith(".")) continue;
    const env = await readJson<Envelope>(join(memberDir, entry));
    if (env) out.push(env);
  }
  return out.sort((a, b) => a.createdAt - b.createdAt);
}

/**
 * 认领一条待读消息：待读位 → delivering（link + unlink，防双活消费）。
 * @throws Error 待读位不存在或已被认领。
 */
export async function claim(teamHome: string, member: string, uuid: string): Promise<Envelope> {
  const memberDir = memberMailboxDir(teamHome, member);
  if (!existsSync(unreadFile(memberDir, uuid))) {
    throw new Error(`unknown envelope ${uuid} in ${member}'s unread segment`);
  }
  const claimed = await linkNoReplace(unreadFile(memberDir, uuid), deliveringFile(memberDir, uuid));
  if (!claimed) {
    throw new Error(`envelope ${uuid} is already claimed or in conflict`);
  }
  await rm(unreadFile(memberDir, uuid));
  return (await readJson<Envelope>(deliveringFile(memberDir, uuid)))!;
}

/**
 * 确认完成：delivering → processed。重复 ack 幂等成功（processed 已存在时
 * 直接清残片返回既有结果语义）。
 */
export async function acknowledge(teamHome: string, member: string, uuid: string): Promise<void> {
  const memberDir = memberMailboxDir(teamHome, member);
  const processing = deliveringFile(memberDir, uuid);
  if (!existsSync(processing)) return; // 幂等：无在途残片
  await import("node:fs/promises").then((m) => m.mkdir(join(memberDir, PROCESSED_DIR), { recursive: true }));
  const ok = await linkNoReplace(processing, processedFile(memberDir, uuid));
  await rm(processing);
  void ok; // false = processed 已有同 id：重复 ack，丢弃本次即可
}

/** 成员信箱收割：先清 processed 命中的 claim 残片，其余交给 P2a TTL 收割。 */
export async function harvestMailbox(
  teamHome: string,
  member: string,
  ttlMs?: number,
): Promise<number> {
  const memberDir = memberMailboxDir(teamHome, member);
  let swept = 0;
  if (existsSync(memberDir)) {
    for (const entry of await readdir(memberDir)) {
      if (!entry.startsWith(DELIVERING_PREFIX) || !entry.endsWith(".json")) continue;
      const uuid = entry.slice(DELIVERING_PREFIX.length, -".json".length);
      if (existsSync(processedFile(memberDir, uuid))) {
        await rm(join(memberDir, entry));
        swept += 1;
      }
    }
  }
  const recovered = await recoverDeliveries(join(teamHome, "mailbox"), ttlMs);
  return swept + recovered.length;
}

src/runtime/paths.ts.source:
/**
 * 目录协议路径解析（v2.2 定稿 §3 布局）。
 *
 * teamHome 即实例根：ADR 0005（#13 冻结口径）下由宿主绑定层解析为
 * `<DSH_HOME>/xiaozhuge/sessions/<主会话id>`，本库不关心其绝对形态，
 * 只按协议拼出各文件/目录的落点。
 */
import { join } from "node:path";

export interface RoomLayout {
  dir: string;
  /** append-only 事件流（仅运行时单写者）。 */
  eventsFile: string;
  /** 黑板 per-role 分片目录。 */
  stateDir: string;
  /** 简报目录。 */
  briefDir: string;
}

export interface Layout {
  teamHome: string;
  teamYaml: string;
  agentsJson: string;
  roomLock: string;
  ledgerTasksDir: string;
  roomsDir: string;
  mailboxDir: string;
  gatesDir: string;
  archiveDir: string;
}

/** 解析实例根下的顶层协议路径。teamHome 即实例根，不再追加 <instance-id> 层。 */
export function layout(teamHome: string): Layout {
  return {
    teamHome,
    teamYaml: join(teamHome, "team.yaml"),
    agentsJson: join(teamHome, "agents.json"),
    roomLock: join(teamHome, "room.lock"),
    ledgerTasksDir: join(teamHome, "ledger", "tasks"),
    roomsDir: join(teamHome, "rooms"),
    mailboxDir: join(teamHome, "mailbox"),
    gatesDir: join(teamHome, "gates"),
    archiveDir: join(teamHome, "archive"),
  };
}

/** 解析单个房间的布局。 */
export function roomLayout(teamHome: string, room: string): RoomLayout {
  const dir = join(layout(teamHome).roomsDir, room);
  return {
    dir,
    eventsFile: join(dir, "events.jsonl"),
    stateDir: join(dir, "state"),
    briefDir: join(dir, "brief"),
  };
}

/** 信箱成员目录。 */
export function memberMailboxDir(teamHome: string, member: string): string {
  return join(layout(teamHome).mailboxDir, member);
}

src/runtime/recovery.ts.source:
/**
 * 崩溃恢复原语（v2.2 定稿 §5 幂等与恢复表）：
 * - 信箱 .delivering-* TTL 收割（omo 模式，P2b 三段式的恢复半边）；
 * - 黑板 running 哨兵整分片作废重做；
 * - 原子写临时残片清扫。
 * 收割/作废结果以清单返回，审计事件由调用方追加到事件流。
 */
import { existsSync } from "node:fs";
import { link, readdir, rm, stat } from "node:fs/promises";
import { join } from "node:path";
import { TMP_PREFIX, readJson } from "./fs-utils.js";
import type { MemberRecord } from "./types.js";

/** 默认投递中 TTL：10 分钟（巡场轮次为分钟级节奏，够宽也够收）。 */
export const DEFAULT_DELIVERING_TTL_MS = 10 * 60_000;

export interface DeliveryRecovery {
  member: string;
  uuid: string;
  /** requeued = 回待读位；dropped = 待读位已存在（processed 防线命中），残片丢弃。 */
  action: "requeued" | "dropped";
}

/**
 * 收割超时的 .delivering-<uuid>.json 残片。
 * 直接 rename 回待读位；目标已存在（EEXIST）即丢弃残片——不做 stat-then-rename
 * （TOCTOU）。已确认过的 uuid 在 processed 位时其待读位不应存在；若存在说明
 * 确认前崩溃，回待读位是正确重投。
 */
export async function recoverDeliveries(
  mailboxDir: string,
  ttlMs = DEFAULT_DELIVERING_TTL_MS,
  now = Date.now(),
): Promise<DeliveryRecovery[]> {
  if (!existsSync(mailboxDir)) return [];
  const result: DeliveryRecovery[] = [];
  for (const member of await readdir(mailboxDir)) {
    const memberDir = join(mailboxDir, member);
    if (!existsSync(memberDir)) continue;
    for (const entry of await readdir(memberDir)) {
      if (!entry.startsWith(".delivering-") || !entry.endsWith(".json")) continue;
      const uuid = entry.slice(".delivering-".length, -".json".length);
      const full = join(memberDir, entry);
      const { mtimeMs } = await stat(full);
      if (now - mtimeMs < ttlMs) continue;
      const target = join(memberDir, `${uuid}.json`);
      // link = 原子 create-if-not-exists：待读位已被占（processed 防线命中）
      // 时 EEXIST，残片丢弃；绝不用 rename（会静默覆盖待读位）。
      try {
        await link(full, target);
        await rm(full);
        result.push({ member, uuid, action: "requeued" });
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "EEXIST") {
          await rm(full);
          result.push({ member, uuid, action: "dropped" });
        } else {
          throw error;
        }
      }
    }
  }
  return result;
}

export interface SentinelRecovery {
  role: string;
  action: "discarded";
}

/**
 * 黑板 running 哨兵处理：state/<role>.json 含 `"status":"running"` 的分片
 * 整体作废重做（unlink 整文件——半新半旧的脏黑板不可复用）。
 */
export async function discardRunningSentinels(stateDir: string): Promise<SentinelRecovery[]> {
  if (!existsSync(stateDir)) return [];
  const result: SentinelRecovery[] = [];
  for (const entry of await readdir(stateDir)) {
    if (!entry.endsWith(".json")) continue;
    const full = join(stateDir, entry);
    const shard = await readJson<{ status?: string }>(full);
    if (shard?.status !== "running") continue;
    await rm(full);
    result.push({ role: entry.replace(/\.json$/, ""), action: "discarded" });
  }
  return result;
}

src/runtime/registry.ts.source:
/**
 * agents.json 成员注册表读写：父死子活对账的数据源（v2.2 定稿 §4）。
 * 单文件原子写；调用方负责持 room.lock 期间再写（本层不做跨进程仲裁）。
 */
import { join } from "node:path";
import type { MemberRecord, TeamRegistry } from "./types.js";
import { readJson, writeJsonAtomic } from "./fs-utils.js";

export class Registry {
  private readonly file: string;

  constructor(teamHome: string) {
    this.file = join(teamHome, "agents.json");
  }

  /** 读注册表；不存在视为空团队。 */
  async read(): Promise<TeamRegistry> {
    const data = await readJson<TeamRegistry>(this.file);
    return data ?? { members: {} };
  }

  /** 整体原子写。 */
  async write(registry: TeamRegistry): Promise<void> {
    await writeJsonAtomic(this.file, registry);
  }

  /** 登记或更新成员。 */
  async upsertMember(record: MemberRecord): Promise<void> {
    const reg = await this.read();
    reg.members[record.member] = record;
    await this.write(reg);
  }

  /** 读单个成员。 */
  async getMember(member: string): Promise<MemberRecord | undefined> {
    const reg = await this.read();
    return reg.members[member];
  }

  /** 更新成员状态与 lastSeen；成员不存在即拒。 */
  async setStatus(member: string, status: MemberRecord["status"]): Promise<void> {
    const reg = await this.read();
    const existing = reg.members[member];
    if (existing === undefined) {
      throw new Error(`member ${member} is not registered`);
    }
    existing.status = status;
    existing.lastSeen = Date.now();
    await this.write(reg);
  }

  /** 存活成员清单（status !== dead），供 reattach 对账。 */
  async liveMembers(): Promise<MemberRecord[]> {
    const reg = await this.read();
    return Object.values(reg.members).filter((m) => m.status !== "dead");
  }
}

src/runtime/template.ts.source:
/**
 * Team Template 与 Role Spec 校验（v2.2 定稿 §7 / §7.1）。
 *
 * 边界：校验器接受**已解析的协议对象**（YAML→对象的解析归宿主绑定层）。
 * 一次收集全部错误不短路；错误码为稳定枚举，供 P3 工具层装配拒绝理由。
 */
import { RESERVED_STAGES, TEMPLATE_SOURCES } from "./types.js";

export interface ValidationError {
  code: string;
  path: string;
  message: string;
}

export interface ValidationResult {
  ok: boolean;
  errors: ValidationError[];
}

const SECTION_ENUM = ["background", "boundary", "acceptance", "forbidden"];

interface LooseRecord {
  [key: string]: unknown;
}

function str(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function collect(
  errors: ValidationError[],
  code: string,
  path: string,
  message: string,
): void {
  errors.push({ code, path, message });
}

// ---------------------------------------------------------------- Role Spec

/** briefing.sections_required 允许的枚举。 */
export const SECTIONS_REQUIRED_ENUM = SECTION_ENUM;

/**
 * 校验单个 Role Spec。
 * 「dod 与 acceptance 至少一处非空」：dod 非空，或 structured 简报的
 * sections_required 含 acceptance——两者满足其一即可。
 */
export function validateRoleSpec(spec: unknown): ValidationResult {
  const errors: ValidationError[] = [];
  if (typeof spec !== "object" || spec === null) {
    return { ok: false, errors: [{ code: "role-not-object", path: "", message: "role spec must be an object" }] };
  }
  const s = spec as LooseRecord;
  if (!str(s.id)) collect(errors, "role-id-required", "id", "role id is required");
  if (!str(s.prompt)) collect(errors, "role-prompt-required", "prompt", "prompt reference is required");

  if (s.briefing !== undefined) {
    if (typeof s.briefing !== "object" || s.briefing === null) {
      collect(errors, "briefing-not-object", "briefing", "briefing must be an object");
    } else {
      const b = s.briefing as LooseRecord;
      if (b.format !== undefined && b.format !== "structured" && b.format !== "freeform") {
        collect(errors, "briefing-format-invalid", "briefing.format", "format must be structured or freeform");
      }
      if (b.sections_required !== undefined) {
        if (!Array.isArray(b.sections_required)) {
          collect(errors, "sections-not-array", "briefing.sections_required", "must be an array");
        } else {
          for (const sec of b.sections_required) {
            if (!SECTION_ENUM.includes(sec as string)) {
              collect(errors, "section-unknown", "briefing.sections_required", `unknown section: ${String(sec)}`);
            }
          }
        }
      }
    }
  }

  if (s.dod !== undefined && !Array.isArray(s.dod)) {
    collect(errors, "dod-not-array", "dod", "dod must be an array of strings");
  }
  const dodNonEmpty =
    Array.isArray(s.dod) &&
    s.dod.some((d) => typeof d === "string" && d.length > 0);
  const hasAcceptanceSection =
    Array.isArray((s.briefing as LooseRecord | undefined)?.sections_required) &&
    ((s.briefing as LooseRecord).sections_required as unknown[]).includes("acceptance");
  if (!dodNonEmpty && !hasAcceptanceSection) {
    collect(
      errors,
      "dod-or-acceptance-required",
      "dod",
      "non-empty dod or briefing.sections_required containing acceptance is required",
    );
  }

  if (s.as_judge !== undefined && typeof s.as_judge !== "boolean") {
    collect(errors, "as-judge-not-bool", "as_judge", "as_judge must be a boolean");
  }
  if (s.max_hops !== undefined) {
    if (typeof s.max_hops !== "number" || !Number.isInteger(s.max_hops) || s.max_hops <= 0) {
      collect(errors, "max-hops-invalid", "max_hops", "max_hops must be a positive integer");
    }
  }
  return { ok: errors.length === 0, errors };
}

/** 校验团队角色定义集：每个 Role Spec 合法，且 as_judge=true 恰好一个。 */
export function validateRoleSet(specs: unknown[]): ValidationResult {
  let errors: ValidationError[] = [];
  let judgeCount = 0;
  specs.forEach((spec, i) => {
    const result = validateRoleSpec(spec);
    errors = errors.concat(result.errors.map((e) => ({ ...e, path: `roles[${i}].${e.path}` })));
    if (typeof spec === "object" && spec !== null && (spec as LooseRecord).as_judge === true) {
      judgeCount += 1;
    }
  });
  if (judgeCount !== 1) {
    errors.push({
      code: "judge-count",
      path: "roles",
      message: `exactly one as_judge role required, found ${judgeCount}`,
    });
  }
  return { ok: errors.length === 0, errors };
}

// ---------------------------------------------------------- Team Template

/**
 * 校验 Team Template（team.yaml 解析后的对象）。
 * roles 为「引用 + 覆盖」形态：元素是字符串引用或覆盖对象（含 id），
 * 定义集由 validateRoleSet 另行校验（定稿 §7.1：角色以独立文件定义）。
 */
export function validateTeamTemplate(tpl: unknown): ValidationResult {
  let errors: ValidationError[] = [];
  if (typeof tpl !== "object" || tpl === null) {
    return { ok: false, errors: [{ code: "template-not-object", path: "", message: "template must be an object" }] };
  }
  const t = tpl as LooseRecord;

  if (!str(t.name)) collect(errors, "name-required", "name", "template name is required");
  if (typeof t.version !== "number" || !Number.isInteger(t.version) || t.version <= 0) {
    collect(errors, "version-invalid", "version", "version must be a positive integer");
  }

  // tiers：2~3 层、id 唯一、prompt 引用非空
  const tiers = Array.isArray(t.tiers) ? (t.tiers as LooseRecord[]) : undefined;
  if (!tiers) {
    collect(errors, "tiers-required", "tiers", "tiers array is required");
  } else {
    if (tiers.length < 2 || tiers.length > 3) {
      collect(errors, "tiers-length", "tiers", "template requires 2 to 3 tiers");
    }
    const ids = new Set<string>();
    tiers.forEach((tier, i) => {
      const p = `tiers[${i}]`;
      if (!str(tier?.id)) collect(errors, "tier-id-required", `${p}.id`, "tier id is required");
      else if (ids.has(tier.id as string)) {
        collect(errors, "tier-duplicate", `${p}.id`, `duplicate tier id: ${tier.id}`);
      } else ids.add(tier.id as string);
      if (!str(tier?.prompt)) collect(errors, "tier-prompt-required", `${p}.prompt`, "tier prompt is required");
    });
  }

  // roles：引用与覆盖形态
  const roles = Array.isArray(t.roles) ? t.roles : undefined;
  if (!roles || roles.length === 0) {
    collect(errors, "roles-required", "roles", "at least one role is required");
  } else {
    const seen = new Set<string>();
    roles.forEach((role, i) => {
      const p = `roles[${i}]`;
      const ref = typeof role === "string" ? role : (role as LooseRecord | null)?.ref;
      const overrideId = typeof role === "object" && role !== null ? (role as LooseRecord).id : undefined;
      const roleId = typeof ref === "string" ? ref : overrideId;
      if (!str(roleId)) {
        collect(errors, "role-ref-required", p, "role must reference a defined role id");
        return;
      }
      if (seen.has(roleId)) collect(errors, "role-duplicate", p, `duplicate role: ${roleId}`);
      seen.add(roleId);
    });
  }

  // comm_mode
  if (t.comm_mode !== undefined && t.comm_mode !== "auto" && t.comm_mode !== "explicit") {
    collect(errors, "comm-mode-invalid", "comm_mode", "comm_mode must be auto or explicit");
  }
  if (t.comm_mode === "explicit") {
    const comm = t.comm;
    if (!Array.isArray(comm)) {
      collect(errors, "explicit-comm-required", "comm", "explicit mode requires a comm whitelist array");
    } else {
      comm.forEach((edge, i) => {
        const e = edge as LooseRecord | null;
        if (
          typeof e !== "object" ||
          e === null ||
          !str(e.from) ||
          !str(e.to)
        ) {
          collect(errors, "comm-edge-invalid", `comm[${i}]`, "edge must have from/to");
        }
      });
    }
  }

  // archives：file|url 两型硬编码；file 型 target 相对路径
  if (t.archives !== undefined) {
    if (!Array.isArray(t.archives)) {
      collect(errors, "archives-not-array", "archives", "archives must be an array");
    } else {
      t.archives.forEach((arc, i) => {
        const p = `archives[${i}]`;
        const a = arc as LooseRecord | null;
        if (typeof a !== "object" || a === null || !str(a.id)) {
          collect(errors, "archive-id-required", `${p}.id`, "archive id is required");
          return;
        }
        if (a.type !== "file" && a.type !== "url") {
          collect(errors, "archive-type-invalid", `${p}.type`, "type must be file or url");
        }
        if (a.type === "file") {
          const target = a.target;
          if (!str(target)) {
            collect(errors, "archive-target-required", `${p}.target`, "file archive target is required");
          } else if (typeof target === "string" && (target.includes("..") || target.startsWith("/"))) {
            collect(errors, "archive-target-escapes", `${p}.target`, "file target must stay inside TEAM_HOME");
          }
        }
        if (a.type === "url" && !str(a.url)) {
          collect(errors, "archive-url-required", `${p}.url`, "url archive requires url field");
        }
      });
    }
  }

  // gates：at 引用 tier 存在
  if (t.gates !== undefined) {
    if (!Array.isArray(t.gates)) {
      collect(errors, "gates-not-array", "gates", "gates must be an array");
    } else {
      const tierIds = new Set((tiers ?? []).map((x) => x?.id as string).filter(Boolean));
      t.gates.forEach((gate, i) => {
        const p = `gates[${i}]`;
        const g = gate as LooseRecord | null;
        if (typeof g !== "object" || g === null || !str(g.id)) {
          collect(errors, "gate-id-required", `${p}.id`, "gate id is required");
          return;
        }
        if (!str(g.at) || !tierIds.has(g.at)) {
          collect(errors, "gate-at-unknown", `${p}.at`, `gate at references unknown tier: ${String(g.at)}`);
        }
        if (g.on !== undefined && !/^stage-enter:[a-z][a-z0-9_-]*$/.test(String(g.on))) {
          collect(errors, "gate-on-invalid", `${p}.on`, "on must look like stage-enter:<state>");
        }
      });
    }
  }

  // resources：正整数
  if (t.resources !== undefined) {
    if (typeof t.resources !== "object" || t.resources === null || Array.isArray(t.resources)) {
      collect(errors, "resources-not-object", "resources", "resources must be an object");
    } else {
      for (const [key, value] of Object.entries(t.resources as LooseRecord)) {
        if (key === "stages_ext") continue;
        if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
          collect(errors, "resource-invalid", `resources.${key}`, "resource limits must be positive integers");
        }
      }
    }
  }

  // stages_ext：不得与保留态冲突
  if (t.stages_ext !== undefined) {
    if (!Array.isArray(t.stages_ext)) {
      collect(errors, "stages-ext-not-array", "stages_ext", "stages_ext must be an array");
    } else {
      for (const stage of t.stages_ext) {
        if (!(RESERVED_STAGES as readonly string[]).includes(stage as string)) continue;
        collect(errors, "stage-reserved", "stages_ext", `stage conflicts with reserved: ${String(stage)}`);
      }
    }
  }

  // 来源标记：缺省通过（实例化快照强制注入），给了就必须合法
  if (t.source !== undefined && !(TEMPLATE_SOURCES as readonly string[]).includes(t.source as string)) {
    collect(errors, "source-invalid", "source", `source must be one of ${TEMPLATE_SOURCES.join("|")}`);
  }

  return { ok: errors.length === 0, errors };
}

